var pos=(v.abd==="pos")||(v.peri==="pos")||(v.lung==="pos");
var ind=(v.abd==="ind")||(v.peri==="ind")||(v.lung==="ind");
if(pos&&v.unstable) return { v:"Positive", u:"scan", i:"<b>Positive</b> with instability. Treat as haemodynamic instability from bleeding (free fluid in the abdomen or pericardium, or chest air/blood). Immediate surgical backup, blood products and source control; do not delay for CT." };
